{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리의 병목에 맞춰 인덱스 추가를 개선책으로 선택한 기술적 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리가 3.2초 걸리던 상황",
          "task": "조회 지연 원인에 맞는 개선책 선택",
          "action": "실행 계획에서 확인한 조회 비용을 실제 조회 조건과 연결해 인덱스 추가의 근거 설명",
          "result": "인덱스 추가로 줄일 수 있다고 판단한 조회 작업 제시"
        },
        "expectedEvidence": [
          "인덱스 추가가 신고 목록 조회의 병목을 줄일 수 있다고 판단한 근거",
          "당시 실행 계획이나 조회 조건에서 그 판단을 뒷받침한 구체적인 특징"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회 쿼리를 개선할 때, 조회 조건에 맞는 인덱스를 추가하기로 결정한 근거는 무엇이었나요?",
      "answerTip": "당시 직접 확인한 사실을 중심으로 짧게 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회의 실제 조건이나 실행 계획에서 확인한 특징을 짚고, 인덱스 추가가 해당 조회 작업을 줄이는 이유를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회에 인덱스를 추가한 이유를 검색 속도 향상이나 전체 조회 감소 같은 일반적인 원리로만 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회에 인덱스를 추가한 근거를 제시하지 않거나, 응답 시간 단축 수치와 작업 사실만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송 오류의 재발을 막는 점검 사항을 스케줄러 중복 실행 원인에 맞게 구체화했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "서버 두 대에서 스케줄러가 동시에 실행되어 알림이 중복 발송된 상황",
          "task": "수정 이후 배포 체크리스트에 재발 방지 점검 사항 반영",
          "action": "체크리스트의 스케줄러 항목에서 실제로 확인하게 한 사항 설명",
          "result": "다음 배포에서 같은 중복 실행 위험을 확인할 수 있는 점검 기준 제시"
        },
        "expectedEvidence": [
          "배포 체크리스트의 스케줄러 항목에 담은 구체적인 확인 사항",
          "해당 확인 사항에서 정상과 중복 실행 위험을 구별하는 기준"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송 오류를 수정한 뒤 배포 체크리스트에 넣은 스케줄러 항목은 구체적으로 어떤 점을 확인하는 항목이었나요?",
      "answerTip": "문서 제목보다 그 안에 실제로 적은 내용을 떠올려 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 체크리스트의 확인 사항을 두 서버의 동시 실행 여부나 잠금 적용 상태 등 실제 장애 원인과 연결해, 무엇을 정상으로 판단하는지 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 체크리스트에서 중복 실행이나 정상 동작을 확인한다고 설명하지만, 무엇을 확인해야 정상인지 구체화하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러 체크리스트에 항목을 추가했다는 사실만 반복하거나, 점검 사항 대신 오류 수정 작업만 설명한다."
          ]
        }
      }
    }
  ]
}

