{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 처방의 적정성을 의심하고 투약을 중단한 판단 근거가 구체적인지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황",
          "task": "처방대로 투약해도 되는지 판단해야 했던 상황",
          "action": "당시 처방 용량을 의심한 구체적인 비교 기준을 중심으로 투약 중단 결정의 근거를 설명",
          "result": "담당의 확인을 통해 입력 오류임을 확인한 사실을 간단히 연결"
        },
        "expectedEvidence": [
          "해당 처방을 그대로 수행하지 않고 투약을 멈추기로 한 구체적인 판단 근거",
          "평소 용량이라고 판단할 때 실제로 비교한 처방이나 투약 정보",
          "그 비교에서 확인한 용량 차이가 처방 확인이 필요한 수준이라고 본 이유"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔던 일에서, 투약을 멈추기로 결정한 구체적인 근거를 말씀해 주세요.",
      "answerTip": "당시 기억나는 사실을 중심으로 본인의 판단을 짧게 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방 용량을 비교한 실제 기준을 제시하며 해당 처방의 적정성을 의심해 투약을 멈춘 근거를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 용량이 평소의 두 배였다는 설명이나 의심스러운 처방은 확인해야 한다는 일반적인 원칙만 제시한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 멈춘 판단 근거를 제시하지 않거나 처방 확인과 무관한 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "인수인계에 포함할 환자 정보를 다음 근무자가 상태를 판단할 수 있는 수준으로 구체화할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰려 인수인계 체크리스트를 개선한 상황",
          "task": "다음 근무자의 환자 상태 판단에 필요한 전달 정보를 선정",
          "action": "전달 항목으로 고른 정보 한 가지를 실제로 무엇을 전달하는 항목인지 드러나게 설명",
          "result": "선택한 정보가 개선된 인수인계 체크리스트에 포함된 사실을 간단히 연결"
        },
        "expectedEvidence": [
          "다음 근무자의 환자 상태 판단에 필요하다고 선정한 인수인계 정보 한 가지",
          "선택한 항목에서 전달하려던 환자별 정보의 구체적인 범위",
          "항목 이름을 넘어 실제 인수인계에 담길 정보의 표현 예시"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트를 개선할 때, 다음 근무자의 환자 상태 판단에 꼭 필요하다고 골랐던 정보 한 가지는 무엇이었나요?",
      "answerTip": "여러 내용을 나열하기보다 한 가지를 골라 구체적으로 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인수인계 정보 한 가지를 고르고, 마지막 진통제의 실제 투여 시점을 구분하는 정보나 필요한 보행 보조 수준처럼 전달할 정보의 범위를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 투여 시각이나 보행 보조 여부처럼 인수인계 항목의 이름만 제시하거나 환자 상태를 잘 전달해야 한다는 일반론에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "선정한 인수인계 정보를 제시하지 않거나 낙상 감소 성과 등 전달 정보와 다른 이야기만 한다."
          ]
        }
      }
    }
  ]
}

